void draw_arrow(VkCommandBuffer cmd, const linalg::vec3 &start,
                const linalg::vec3 &end, uint32_t color)
{
  using namespace linalg;

  vec3 dir = end - start;
  float len = length(dir);
  if (len < 0.0001f)
    return;

  vec3 w = dir * (1.0f / len);

  // Find arbitrary up vector
  vec3 up = {{0, 1, 0}};
  if (std::abs(dot(w, up)) > 0.99f)
  {
    up = {{1, 0, 0}};
  }

  vec3 u = normalize(cross(up, w));
  vec3 v = cross(w, u);

  float head_len = 0.5f;
  float head_width = 0.2f;
  float shaft_width = 0.05f;

  if (len < head_len)
  {
    head_len = len; // Arrow is just head if too short
  }

  vec3 shaft_end = start + w * (len - head_len);

  // -- Draw Shaft (AABB-like Box) --
  // If we really want an "AABB" as the user asked ("from an AABB"),
  // we align it with the arrow frame. It's an OBB really.
  if (len > head_len)
  {
    float sw = shaft_width * 0.5f;
    vec3 c1 = start - u * sw - v * sw;
    vec3 c2 = start + u * sw - v * sw;
    vec3 c3 = start + u * sw + v * sw;
    vec3 c4 = start - u * sw + v * sw;

    vec3 c5 = shaft_end - u * sw - v * sw;
    vec3 c6 = shaft_end + u * sw - v * sw;
    vec3 c7 = shaft_end + u * sw + v * sw;
    vec3 c8 = shaft_end - u * sw + v * sw;

    // Base
    DrawLine(cmd, c1, c2, color);
    DrawLine(cmd, c2, c3, color);
    DrawLine(cmd, c3, c4, color);
    DrawLine(cmd, c4, c1, color);

    // Top
    DrawLine(cmd, c5, c6, color);
    DrawLine(cmd, c6, c7, color);
    DrawLine(cmd, c7, c8, color);
    DrawLine(cmd, c8, c5, color);

    // Sides
    DrawLine(cmd, c1, c5, color);
    DrawLine(cmd, c2, c6, color);
    DrawLine(cmd, c3, c7, color);
    DrawLine(cmd, c4, c8, color);
  }

  // -- Draw Head (Pyramid) --
  {
    float hw = head_width * 0.5f;
    vec3 b1 = shaft_end - u * hw - v * hw;
    vec3 b2 = shaft_end + u * hw - v * hw;
    vec3 b3 = shaft_end + u * hw + v * hw;
    vec3 b4 = shaft_end - u * hw + v * hw;

    // Base
    DrawLine(cmd, b1, b2, color);
    DrawLine(cmd, b2, b3, color);
    DrawLine(cmd, b3, b4, color);
    DrawLine(cmd, b4, b1, color);

    // Tip
    DrawLine(cmd, b1, end, color);
    DrawLine(cmd, b2, end, color);
    DrawLine(cmd, b3, end, color);
    DrawLine(cmd, b4, end, color);
  }
}

void draw_wedge(VkCommandBuffer cmd, const shared::wedge_t &wedge,
                uint32_t color)
{
  auto points = shared::get_wedge_points(wedge);

  // Draw Base Loop (0-1-2-3)
  DrawLine(cmd, points[0], points[1], color);
  DrawLine(cmd, points[1], points[2], color);
  DrawLine(cmd, points[2], points[3], color);
  DrawLine(cmd, points[3], points[0], color);

  // Draw Top Edge (4-5)
  DrawLine(cmd, points[4], points[5], color);

  // Connect Top Edge to Base
  const float epsilon = 0.001f;
  linalg::vec3 edge_delta = points[5] - points[4];
  bool edge_along_x = std::abs(edge_delta.x) > std::abs(edge_delta.z);

  for (int i = 4; i <= 5; ++i)
  {
    linalg::vec3 top = points[i];
    for (int j = 0; j < 4; ++j)
    {
      linalg::vec3 base = points[j];
      bool share_x = std::abs(top.x - base.x) < epsilon;
      bool share_z = std::abs(top.z - base.z) < epsilon;

      if (edge_along_x)
      {
        // Edge along X -> Slope along Z. Connect if Share X.
        if (share_x)
          DrawLine(cmd, top, base, color);
      }
      else
      {
        // Edge along Z -> Slope along X. Connect if Share Z.
        if (share_z)
          DrawLine(cmd, top, base, color);
      }
    }
  }
}

void draw_hitbox_sphere(VkCommandBuffer cmd, const linalg::vec3 &center,
                        float radius, uint32_t color)
{
  // Draw sphere using primitive mesh
  auto sphere_mesh = assets::get_primitive_mesh("sphere");
  if (!sphere_mesh.valid())
    return;

  // Scale by radius * 2 (primitive sphere has diameter 1.0, radius 0.5)
  linalg::vec3 scale = {radius * 2.0f, radius * 2.0f, radius * 2.0f};
  DrawMeshWireframe(cmd, center, scale, sphere_mesh, color);
}

void draw_hitbox_capsule(VkCommandBuffer cmd, const linalg::vec3 &center,
                         float radius, float half_height, uint32_t color)
{
  // Capsule = cylinder + sphere on top + sphere on bottom
  // Center is at the middle of the capsule

  // Draw cylinder body
  auto cylinder_mesh = assets::get_primitive_mesh("cylinder");
  if (cylinder_mesh.valid())
  {
    // Cylinder primitive is 1 unit tall, scale to full height (2 * half_height)
    // and radius * 2 for diameter
    linalg::vec3 cyl_scale = {radius * 2.0f, half_height * 2.0f, radius * 2.0f};
    DrawMeshWireframe(cmd, center, cyl_scale, cylinder_mesh, color);
  }

  // Draw top hemisphere (full sphere for simplicity)
  linalg::vec3 top_center = {center.x, center.y + half_height, center.z};
  draw_hitbox_sphere(cmd, top_center, radius, color);

  // Draw bottom hemisphere
  linalg::vec3 bottom_center = {center.x, center.y - half_height, center.z};
  draw_hitbox_sphere(cmd, bottom_center, radius, color);
}

